module.exports = /*#__PURE__*/JSON.parse('{"header":{"home":"Home","topJournalists":"Top journalists","explore":"Explore","about":"About","joinSikiya":"Join sikiya","learnMore":"Learn more"},"languageSwitcher":{"label":"Language","en":"English","fr":"French"},"hero":{"tagline":"Built for Africa\'s next generation of journalism","titleLead":"News that inspire Africa\'s","titleAccent":"conversations","subtitle":"A platform dedicated to news that inspire conversations on the political, economic, social, and cultural dimensions shaping the continent.","downloadButton":"Download Sikiya","topJournalistsButton":"Our top journalists","missionTitle":"Our Mission"},"mission":{"previousSlide":"Previous slide","nextSlide":"Next slide","goToSlide":"Go to slide {n}","slides":[{"title":"Where Africa Speaks","body":"Vote, take a stance, and join structured discussions through dedicated lanes. Conversations are organized by topic and perspective, creating space for constructive dialogue where communities, journalists, and public voices can share and challenge ideas."},{"title":"Beyond the Headlines","body":"Read perspectives from public figures, journalists, analysts, and academics through approved article commentary and discussions. Verified voices help share their perspectives on articles, shaping informed conversations around events across the continent."},{"title":"Trust You Can Measure","body":"A transparent trust score and publisher verification system keeps journalism accountable. Publishers evaluate articles based on reporting quality, fact-checking practices, and editorial standards, giving readers clear insight into the credibility behind every source."},{"title":"An Africa-Focused Network","body":"Sikiya is building an Africa-wide network of affiliated and freelance journalists delivering real-time, on-the-ground local perspectives, while verified public figures share their perspectives directly with communities across the continent.","ctaLabel":"Explore the Network","ctaHref":"/top_contributors"}]},"heroPosts":{"empower":{"title":"Empower Communities with Knowledge","description":"Share your news and opinions to keep everyone updated on important matters."},"criticalThinking":{"title":"Encourage Critical Thinking","description":"Comment on articles to share your point of view and enrich everyone\'s understanding."},"engagement":{"title":"Spark Meaningful Engagement","description":"Take part in relevant and respectful conversations that matter."}},"primaryFeatures":{"title":"Everything you need to share your story","subtitle":"A complete platform for journalists, writers, and content creators to share insights about Africa.","users":"Users","journalists":"Journalists","journalistFeatures":{"publish":{"title":"Publish your knowledge through articles","description":"Become a Sikiya-certified journalist and start sharing your insights with the world."},"video":{"title":"Share your insights through short videos","description":"Become a Sikiya-certified journalist and publish short videos to engage your audience."}},"userFeatures":{"conversations":{"title":"Join meaningful conversations with fellow Africans","description":"Connect with an active community discussing political, economic, social, and cultural topics that matter."}}},"secondaryFeatures":{"title":"Our Core Values","subtitle":"We are committed to truth, accuracy, coverage, open dialogue, and respect in everything we do.","truth":{"name":"Truth & Accuracy","summary":"We deliver verified facts and hold journalists accountable for accurate reporting.","description":"Every story matters. We spotlight events that shape our communities and ensure that information is verified and trustworthy."},"coverage":{"name":"Coverage","summary":"Every story matters. We spotlight events that shape our communities.","description":"We believe in comprehensive coverage of African stories, from local events to continental issues that impact our communities."},"dialogue":{"name":"Open Dialogue","summary":"We welcome diverse voices and encourage meaningful, constructive conversations.","description":"We foster a safe environment where every perspective is valued and heard. Join the conversation and share your insights."}},"testimonials":{"title":"Trusted by journalists and readers across Africa.","subtitle":"Join a growing community of journalists, writers, and readers who are shaping the narrative about Africa\'s future.","testimonials":[{"content":"Sikiya has given me a platform to share stories that matter to my community. The engagement and dialogue it fosters is exactly what African journalism needs.","author":"Amina Okafor","role":"Independent Journalist"},{"content":"As a reader, I love how Sikiya brings diverse perspectives together. It\'s refreshing to see African stories told by African voices.","author":"Kwame Mensah","role":"Community Advocate"},{"content":"The platform\'s commitment to truth and accuracy is evident in every article. I trust Sikiya to deliver verified, meaningful content about our continent.","author":"Fatima Hassan","role":"Media Professional"},{"content":"Sikiya has created a space where open dialogue is not just encouraged, but celebrated. It\'s empowering to be part of this community.","author":"David Okonkwo","role":"Content Creator"},{"content":"I appreciate how Sikiya covers stories that shape our communities. Every article, every video, every discussion contributes to a better understanding of Africa.","author":"Sarah Mwangi","role":"Educator & Writer"},{"content":"The respect and integrity shown on this platform make it a safe space for meaningful conversations. Sikiya is building something special.","author":"Tunde Adebayo","role":"Political Analyst"}]},"callToAction":{"title":"Ready to contribute?","subtitle":"Join the Sikiya community and start sharing your stories, articles, and insights about Africa. Download our mobile app to get started.","button":"Download Sikiya"},"faqs":{"title":"Frequently asked questions","subtitle":"If you can\'t find what you\'re looking for, reach out to our support team through the app or email us directly.","questions":[{"question":"How do I start contributing to Sikiya?","answer":"Download our mobile app from the App Store or Google Play Store. Once you create an account, you can start sharing articles, videos, and engaging with the community."},{"question":"Who can contribute content to Sikiya?","answer":"Anyone can contribute! We welcome journalists, writers, content creators, and anyone with insights about Africa. All content is subject to our community guidelines."},{"question":"Is Sikiya free to use?","answer":"Yes, Sikiya is free for readers and contributors. We believe in making information accessible to everyone."},{"question":"How does Sikiya ensure content accuracy?","answer":"We have a verification process and hold journalists accountable for accurate reporting. Our community also helps flag any issues with content."},{"question":"What topics can I write about on Sikiya?","answer":"We focus on political, economic, social, and cultural dimensions shaping Africa. We welcome diverse perspectives and encourage meaningful dialogue."},{"question":"Can I use Sikiya on my computer?","answer":"Currently, Sikiya is available as a mobile app for iOS and Android. We are working on a web version for the future."},{"question":"How do I report inappropriate content?","answer":"You can report content directly through the app. Our moderation team reviews all reports to maintain a respectful and safe community environment."},{"question":"How can I contact Sikiya support?","answer":"You can reach out to us through the app or email us directly. We aim to respond to all inquiries within 24-48 hours."},{"question":"Does Sikiya have a journalist verification program?","answer":"Yes, we have a verification program for journalists. Verified journalists have additional features and their content is highlighted on the platform."}]},"aboutPage":{"hero":{"title":"Africa deserves better conversations.","subtitle":"Sikiya was built to create a more accountable, informed, and connected media ecosystem across Africa, where journalists, experts, and communities engage beyond the headlines."},"problemResponse":{"problemTitle":"The Problem","problemItems":[{"title":"Biased national media can limit diverse perspectives","body":"Political and institutional interests often shape coverage, leaving many communities underrepresented."},{"title":"Informal social networks accelerate misinformation","body":"News shared through WhatsApp, Facebook, X, and group chats can spread unverified information quickly."},{"title":"Political headlines overshadow everyday progress","body":"Innovation, culture, business, and community achievements often receive limited attention."},{"title":"Limited coverage leaves local communities unheard","body":"Many important stories and perspectives never reach major media platforms."},{"title":"News needs more meaningful public discussion","body":"Communities should be able to debate, explain, and engage with important stories together."}],"responseTitle":"The Sikiya Response","responseIntro":"Sikiya combines verified journalism, structured discussions, trust metrics, regional perspectives, and expert insights into one unified platform.","responseItems":[{"title":"On-the-ground coverage brings local stories forward","body":"By supporting both freelance and affiliated journalists, Sikiya encourages real-time reporting on communities, innovation, business, culture, and everyday progress across Africa."},{"title":"A wide network of journalists and public voices","body":"Sikiya welcomes affiliated and independent journalists, alongside public figures, podcasters, YouTubers, and experts who can support, challenge, and add context directly to articles."},{"title":"Verification and trust scores promote accountability","body":"A transparent verification process and trust score system help readers identify credible journalists and track sources that repeatedly spread misinformation."},{"title":"Structured discussions encourage public participation","body":"Dedicated discussion lanes allow communities to vote, share opinions, and take part in informed conversations around important issues."}]},"builtForAfrica":{"title":"Built for Africa","subtitle":"From Lagos to Nairobi, Cape Town to Kinshasa, Sikiya is building a platform shaped by the realities, languages, and perspectives of communities across Africa","comingSoon":"Coming soon","locations":[{"city":"Lagos","country":"Nigeria"},{"city":"Nairobi","country":"Kenya"},{"city":"Cape Town","country":"South Africa"},{"city":"Kinshasa","country":"DR Congo"},{"city":"Accra","country":"Ghana"},{"city":"Cairo","country":"Egypt"},{"city":"Addis Ababa","country":"Ethiopia"},{"city":"Kigali","country":"Rwanda"}]}},"footer":{"copyright":"Copyright © {year} Sikiya. All rights reserved."},"topContributors":{"title":"Top Journalists","subtitle":"Meet the passionate journalists, writers, and content creators who are shaping the dialogue on Africa\'s future through their insightful articles and stories.","trustScore":"Trust Score","articlesLabel":"Articles","verifiedProfile":"Verified journalist","profiles":[{"name":"Amara Okafor","role":"Investigative Journalist","location":"Lagos, Nigeria","bio":"Award-winning reporter covering West African politics and economic development","tags":["Politics","Economy","Governance"],"trustScore":94,"articleCount":127,"profileImageUrl":""},{"name":"Kwame Mensah","role":"Photojournalist","location":"Accra, Ghana","bio":"Documenting untold stories through powerful visual narratives","tags":["Visual Stories","Culture","Society"],"trustScore":91,"articleCount":89,"profileImageUrl":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&h=400&q=80"},{"name":"Zainab Hassan","role":"Data Journalist","location":"Nairobi, Kenya","bio":"Using data to uncover patterns in climate change and public health","tags":["Data Analysis","Climate","Health"],"trustScore":97,"articleCount":156,"profileImageUrl":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=400&h=400&q=80"},{"name":"Thabo Ndlovu","role":"Editor & Columnist","location":"Johannesburg, South Africa","bio":"Senior editor with 15 years covering social justice across Southern Africa","tags":["Opinion","Human Rights","Justice"],"trustScore":96,"articleCount":203,"profileImageUrl":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=400&h=400&q=80"}]},"contribute":{"title":"Start Contributing","subtitle":"Join the Sikiya community and start sharing your stories, articles, and insights about Africa. Download our mobile app to get started.","appStore":{"downloadOn":"Download on the","name":"App Store"},"googlePlay":{"getItOn":"Get it on","name":"Google Play"},"whatYouCanDo":{"title":"What you can do on Sikiya","shareArticles":{"title":"Share Articles","description":"Publish your articles and stories about political, economic, social, and cultural dimensions shaping Africa."},"createVideos":{"title":"Create Videos","description":"Share short videos and engage with the community through visual storytelling."},"joinDiscussions":{"title":"Join Discussions","description":"Engage in meaningful conversations, comment on articles, and connect with journalists and readers."}}},"explore":{"phonePlaceholder":"Replace with your screenshot","startContributing":{"title":"Start Contributing","paragraph1":"Join the Sikiya community and start sharing your stories, articles, and insights about Africa.","paragraph2":"Download our mobile app to get started."},"forUsers":{"title":"For Our Users","items":[{"title":"Personalized News Feed","description":"Get stories tailored to your interests and location across Africa."},{"title":"Trust Scores at a Glance","description":"See credibility metrics for every article and publisher instantly."},{"title":"Discussion Lanes","description":"Join structured conversations organized by topic and viewpoint."},{"title":"Audio Insights","description":"Listen to expert analysis and deep-dive podcasts on the go."}]},"forJournalists":{"title":"For Journalists","items":[{"title":"Publish Your Stories","description":"Submit articles with our intuitive mobile editor and reach readers across Africa."},{"title":"Build Your Profile","description":"Showcase your work, verification status, and trust score to build credibility."},{"title":"Track Your Impact","description":"Monitor readership, engagement, and community feedback on your journalism."}]}}}');

