module.exports = /*#__PURE__*/JSON.parse('{"header":{"home":"Accueil","topJournalists":"Top journalistes","explore":"Explorer","about":"À propos","joinSikiya":"Rejoindre Sikiya","learnMore":"En savoir plus"},"languageSwitcher":{"label":"Langue","en":"Anglais","fr":"Français"},"hero":{"tagline":"Au service de la prochaine génération de journalistes africains","titleLead":"Des news qui inspirent les","titleAccent":"conversations en Afrique","subtitle":"Une plateforme dédiée aux actualités qui inspirent les conversations sur les dimensions politiques, économiques, sociales et culturelles qui façonnent le continent.","downloadButton":"Télécharger Sikiya","topJournalistsButton":"Top journalistes","missionTitle":"Notre Mission"},"mission":{"previousSlide":"Diapositive précédente","nextSlide":"Diapositive suivante","goToSlide":"Aller à la diapositive {n}","slides":[{"title":"Là où l’Afrique s’exprime","body":"Votez, prenez position et participez à des discussions structurées à travers des espaces dédiés. Les conversations sont organisées par sujet et par perspective afin de favoriser un dialogue constructif entre communautés, journalistes et voix publiques."},{"title":"Au-delà des titres","body":"Découvrez les points de vue de personnalités publiques, journalistes, analystes et universitaires à travers des commentaires et discussions approuvés autour des articles. Des voix vérifiées enrichissent les échanges et apportent plus de contexte aux événements qui façonnent le continent."},{"title":"Une confiance mesurable","body":"Un système transparent de score de confiance et de vérification des éditeurs renforce la responsabilité journalistique. Les articles sont évalués selon la qualité du reportage, les pratiques de vérification des faits et les standards éditoriaux."},{"title":"Un réseau centré sur l’Afrique","body":"Sikiya construit un réseau africain de journalistes affiliés et indépendants offrant des perspectives locales et des reportages en temps réel, tandis que des personnalités publiques vérifiées partagent directement leurs points de vue avec les communautés du continent.","ctaLabel":"Découvrir le réseau","ctaHref":"/top_contributors"}]},"heroPosts":{"empower":{"title":"Informer et inspirer les communautés","description":"Partagez vos actualités et vos opinions pour tenir tout le monde informé des sujets importants."},"criticalThinking":{"title":"Encourager la pensée critique","description":"Commentez les articles pour partager votre point de vue et enrichir la compréhension de tous."},"engagement":{"title":"Favoriser un engagement significatif","description":"Participez à des conversations pertinentes et respectueuses qui comptent."}},"primaryFeatures":{"title":"Tout ce dont vous avez besoin pour partager votre histoire","subtitle":"Une plateforme complète pour journalistes, écrivains et créateurs de contenu souhaitant partager leurs idées sur l\'Afrique.","users":"Utilisateurs","journalists":"Journalistes","journalistFeatures":{"publish":{"title":"Publiez vos connaissances à travers des articles","description":"Devenez journaliste certifié Sikiya et commencez à partager vos idées avec le monde."},"video":{"title":"Partagez vos idées à travers de courtes vidéos","description":"Devenez journaliste certifié Sikiya et publiez de courtes vidéos pour engager votre audience."}},"userFeatures":{"conversations":{"title":"Participez à des conversations constructives avec d’autres Africains","description":"Connectez-vous avec une communauté active discutant de sujets politiques, économiques, sociaux et culturels importants."}}},"secondaryFeatures":{"title":"Nos Valeurs Fondamentales","subtitle":"Nous sommes engagés envers la vérité, l\'exactitude, la couverture, le dialogue ouvert et le respect dans tout ce que nous faisons.","truth":{"name":"Vérité et Exactitude","summary":"Nous livrons des faits vérifiés et tenons les journalistes responsables de leurs rapports exacts.","description":"Chaque histoire compte. Nous mettons en lumière les événements qui façonnent nos communautés et garantissons que les informations sont vérifiées et fiables."},"coverage":{"name":"Couverture","summary":"Chaque histoire compte. Nous mettons en lumière les événements qui façonnent nos communautés.","description":"Nous croyons en une couverture complète des histoires africaines, des événements locaux aux questions continentales qui impactent nos communautés."},"dialogue":{"name":"Dialogue Ouvert","summary":"Nous accueillons des voix diverses et encourageons des conversations constructives et significatives.","description":"Nous favorisons un environnement sûr où chaque perspective est valorisée et entendue. Rejoignez la conversation et partagez vos idées."}},"testimonials":{"title":"Approuvé par les journalistes et les lecteurs à travers l\'Afrique.","subtitle":"Rejoignez une communauté croissante de journalistes, d\'écrivains et de lecteurs qui façonnent le récit de l\'avenir de l\'Afrique.","testimonials":[{"content":"Sikiya m\'a donné une plateforme pour partager des histoires qui comptent pour ma communauté. L\'engagement et le dialogue qu\'elle favorise sont exactement ce dont le journalisme africain a besoin.","author":"Amina Okafor","role":"Journaliste Indépendante"},{"content":"En tant que lecteur, j\'aime comment Sikiya rassemble des perspectives diverses. C\'est rafraîchissant de voir des histoires africaines racontées par des voix africaines.","author":"Kwame Mensah","role":"Défenseur de la Communauté"},{"content":"L\'engagement de la plateforme envers la vérité et l\'exactitude est évident dans chaque article. Je fais confiance à Sikiya pour livrer du contenu vérifié et significatif sur notre continent.","author":"Fatima Hassan","role":"Professionnelle des Médias"},{"content":"Sikiya a créé un espace où le dialogue ouvert n\'est pas seulement encouragé, mais célébré. C\'est stimulant de faire partie de cette communauté.","author":"David Okonkwo","role":"Créateur de Contenu"},{"content":"J\'apprécie comment Sikiya couvre les histoires qui façonnent nos communautés. Chaque article, chaque vidéo, chaque discussion contribue à une meilleure compréhension de l\'Afrique.","author":"Sarah Mwangi","role":"Éducatrice et Écrivaine"},{"content":"Le respect et l\'intégrité démontrés sur cette plateforme en font un espace sûr pour des conversations significatives. Sikiya construit quelque chose de spécial.","author":"Tunde Adebayo","role":"Analyste Politique"}]},"callToAction":{"title":"Prêt à contribuer ?","subtitle":"Rejoignez la communauté Sikiya et commencez à partager vos histoires, articles et idées sur l\'Afrique. Téléchargez notre application mobile pour commencer.","button":"Télécharger Sikiya"},"faqs":{"title":"Questions fréquemment posées","subtitle":"Si vous ne trouvez pas ce que vous cherchez, contactez notre équipe de support via l\'application ou envoyez-nous un e-mail directement.","questions":[{"question":"Comment puis-je commencer à contribuer à Sikiya ?","answer":"Téléchargez notre application mobile depuis l\'App Store ou Google Play Store. Une fois que vous avez créé un compte, vous pouvez commencer à partager des articles, des vidéos et interagir avec la communauté."},{"question":"Qui peut contribuer du contenu à Sikiya ?","answer":"Tout le monde peut contribuer ! Nous accueillons les journalistes, les écrivains, les créateurs de contenu et toute personne ayant des idées sur l\'Afrique. Tout contenu est soumis à nos directives communautaires."},{"question":"Sikiya est-il gratuit ?","answer":"Oui, Sikiya est gratuit pour les lecteurs et les contributeurs. Nous croyons en l\'accessibilité de l\'information pour tous."},{"question":"Comment Sikiya garantit-il l\'exactitude du contenu ?","answer":"Nous avons un processus de vérification et tenons les journalistes responsables de rapports exacts. Notre communauté aide également à signaler tout problème avec le contenu."},{"question":"Sur quels sujets puis-je écrire sur Sikiya ?","answer":"Nous nous concentrons sur les dimensions politiques, économiques, sociales et culturelles qui façonnent l\'Afrique. Nous accueillons des perspectives diverses et encourageons le dialogue significatif."},{"question":"Puis-je utiliser Sikiya sur mon ordinateur ?","answer":"Actuellement, Sikiya est disponible sous forme d\'application mobile pour iOS et Android. Nous travaillons sur une version web pour l\'avenir."},{"question":"Comment puis-je signaler du contenu inapproprié ?","answer":"Vous pouvez signaler du contenu directement via l\'application. Notre équipe de modération examine tous les rapports pour maintenir un environnement communautaire respectueux et sûr."},{"question":"Comment puis-je contacter le support de Sikiya ?","answer":"Vous pouvez nous contacter via l\'application ou nous envoyer un e-mail directement. Nous visons à répondre à toutes les demandes dans les 24 à 48 heures."},{"question":"Sikiya a-t-il un programme de vérification pour les journalistes ?","answer":"Oui, nous avons un programme de vérification pour les journalistes. Les journalistes vérifiés ont des fonctionnalités supplémentaires et leur contenu est mis en évidence sur la plateforme."}]},"aboutPage":{"hero":{"title":"L\'Afrique mérite de meilleures conversations.","subtitle":"Sikiya a été conçue pour construire un écosystème médiatique africain plus responsable, plus informé et plus connecté, où journalistes, experts et communautés peuvent échanger au-delà des gros titres."},"problemResponse":{"problemTitle":"Le problème","problemItems":[{"title":"Les médias nationaux biaisés peuvent limiter les perspectives diverses","body":"Les intérêts politiques et institutionnels façonnent souvent la couverture, laissant de nombreuses communautés sous-représentées."},{"title":"Les réseaux sociaux informels accélèrent la désinformation","body":"Les actualités partagées via WhatsApp, Facebook, X et les discussions de groupe peuvent diffuser rapidement des informations non vérifiées."},{"title":"Les titres politiques éclipsent le progrès du quotidien","body":"L\'innovation, la culture, l\'économie et les réussites communautaires reçoivent souvent peu d\'attention."},{"title":"Une couverture limitée laisse les communautés locales sans voix","body":"De nombreuses histoires et perspectives importantes n\'atteignent jamais les grandes plateformes médiatiques."},{"title":"L\'actualité a besoin d\'un débat public plus significatif","body":"Les communautés devraient pouvoir débattre, expliquer et s\'engager ensemble sur les sujets importants."}],"responseTitle":"La réponse Sikiya","responseIntro":"Sikiya réunit journalisme vérifié, discussions structurées, indicateurs de confiance, perspectives régionales et analyses d\'experts au sein d\'une même plateforme.","responseItems":[{"title":"Une couverture de terrain met en avant les histoires locales","body":"En soutenant les journalistes indépendants et affiliés, Sikiya encourage des reportages en temps réel sur les communautés, l’innovation, l’économie, la culture et le progrès quotidien à travers l’Afrique."},{"title":"Un vaste réseau de journalistes et de voix publiques","body":"Sikiya accueille des journalistes affiliés et indépendants, ainsi que des personnalités publiques, podcasteurs, YouTubeurs et experts capables d’apporter du contexte, de soutenir ou de remettre en question les articles."},{"title":"La vérification et les scores de confiance renforcent la responsabilité","body":"Un système transparent de vérification et de score de confiance aide les lecteurs à identifier les journalistes crédibles et à repérer les sources qui diffusent régulièrement de la désinformation."},{"title":"Des discussions structurées favorisent la participation publique","body":"Des espaces de discussion dédiés permettent aux communautés de voter, de partager leurs opinions et de participer à des conversations constructives sur des sujets importants."}]},"builtForAfrica":{"title":"Pensée pour l\'Afrique","subtitle":"De Lagos à Nairobi, du Cap à Kinshasa, Sikiya construit une plateforme forgée par les réalités, les langues et les perspectives des communautés à travers l\'Afrique","comingSoon":"Bientôt","locations":[{"city":"Lagos","country":"Nigeria"},{"city":"Nairobi","country":"Kenya"},{"city":"Le Cap","country":"Afrique du Sud"},{"city":"Kinshasa","country":"RDC"},{"city":"Accra","country":"Ghana"},{"city":"Le Caire","country":"Égypte"},{"city":"Addis-Abeba","country":"Éthiopie"},{"city":"Kigali","country":"Rwanda"}]}},"footer":{"copyright":"Droits d\'auteur © {year} Sikiya. Tous droits réservés."},"topContributors":{"title":"Top journalistes","subtitle":"Découvrez les journalistes, auteurs et créateurs de contenu passionnés qui façonnent le dialogue sur l\'avenir de l\'Afrique à travers leurs reportages et leurs histoires.","trustScore":"Score de confiance","articlesLabel":"Articles","verifiedProfile":"Journaliste vérifié","profiles":[{"name":"Amara Okafor","role":"Journaliste d\'investigation","location":"Lagos, Nigeria","bio":"Récompensée pour ses enquêtes sur la politique et le développement économique en Afrique de l\'Ouest","tags":["Politique","Économie","Gouvernance"],"trustScore":94,"articleCount":127,"profileImageUrl":""},{"name":"Kwame Mensah","role":"Photojournaliste","location":"Accra, Ghana","bio":"Documentation de récits méconnus à travers des narratives visuelles puissantes","tags":["Récits visuels","Culture","Société"],"trustScore":91,"articleCount":89,"profileImageUrl":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&h=400&q=80"},{"name":"Zainab Hassan","role":"Journaliste data","location":"Nairobi, Kenya","bio":"Analyse des données pour révéler des tendances en climat et en santé publique","tags":["Analyse de données","Climat","Santé"],"trustScore":97,"articleCount":156,"profileImageUrl":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=400&h=400&q=80"},{"name":"Thabo Ndlovu","role":"Rédacteur & chroniqueur","location":"Johannesburg, Afrique du Sud","bio":"Rédacteur senior avec 15 ans d\'expérience sur la justice sociale en Afrique australe","tags":["Opinion","Droits humains","Justice"],"trustScore":96,"articleCount":203,"profileImageUrl":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=400&h=400&q=80"}]},"contribute":{"title":"Commencez à Contribuer","subtitle":"Rejoignez la communauté Sikiya et commencez à partager vos histoires, articles et idées sur l\'Afrique. Téléchargez notre application mobile pour commencer.","appStore":{"downloadOn":"Télécharger sur","name":"App Store"},"googlePlay":{"getItOn":"Disponible sur","name":"Google Play"},"whatYouCanDo":{"title":"Ce que vous pouvez faire sur Sikiya","shareArticles":{"title":"Partager des Articles","description":"Publiez vos articles et histoires sur les dimensions politiques, économiques, sociales et culturelles qui façonnent l\'Afrique."},"createVideos":{"title":"Créer des Vidéos","description":"Partagez de courtes vidéos et engagez-vous avec la communauté à travers la narration visuelle."},"joinDiscussions":{"title":"Rejoindre les Discussions","description":"Participez à des conversations constructives, commentez les articles et connectez-vous avec les journalistes et les lecteurs."}}},"explore":{"phonePlaceholder":"Remplacez par votre capture d’écran","startContributing":{"title":"Commencez à contribuer","paragraph1":"Rejoignez la communauté Sikiya et partagez vos histoires, articles et analyses sur l’Afrique.","paragraph2":"Téléchargez notre application mobile pour commencer."},"forUsers":{"title":"Pour nos lecteurs","items":[{"title":"Fil d’actualités personnalisé","description":"Recevez des articles adaptés à vos centres d’intérêt et à votre localisation en Afrique."},{"title":"Scores de confiance visibles","description":"Consultez en un instant les indicateurs de crédibilité pour chaque article et éditeur."},{"title":"Salons de discussion","description":"Participez à des conversations structurées par thème et par regard sur l’actualité."},{"title":"Analyses audio","description":"Écoutez des analyses d’experts et des formats podcast où que vous soyez."}]},"forJournalists":{"title":"Pour les journalistes","items":[{"title":"Publiez vos reportages","description":"Rédigez depuis l’éditeur mobile et touchez des lecteurs partout en Afrique."},{"title":"Construisez votre profil","description":"Mettez en avant votre travail, votre statut vérifié et votre score de confiance."},{"title":"Mesurez votre impact","description":"Suivez audience, engagement et retours de la communauté sur vos articles."}]}}}');

